Create Product.code:
// Create a product in the catalogue.
// Paths are relative to the baseUrl, which already ends in /api.
// request() resolves $ references (get()/post() pass them through unresolved).
request('POST', 'products', {
  body: {
    name: $.data.productName, // e.g. 'Amoxicillin 250mg capsules'
    description: $.data.description,
    // Category the product belongs to.
    category: { id: $.data.categoryId },
    unitOfMeasure: 'each',
    // Track lot numbers and expiry dates (typical for medicines).
    lotAndExpiryControl: true,
  },
});

Update Product.code:
// Update a product (OpenBoxes uses POST for updates).
request('POST', `products/${$.data.productId}`, {
  body: {
    name: $.data.productName,
    description: $.data.description,
    active: true,
  },
});

Create Stock Movement.code:
// Create a stock movement from a central warehouse to a health facility.
request('POST', 'stockMovements', {
  body: {
    name: `Monthly resupply - ${$.data.facilityName}`,
    description: 'Routine monthly replenishment',
    'origin.id': $.data.warehouseId, // sending depot
    'destination.id': $.data.facilityId, // receiving facility
    'requestedBy.id': $.data.requesterId,
    dateRequested: $.data.dateRequested, // MM/DD/YYYY, e.g. '11/02/2026'
  },
});

Add Line Items To Stock Movement.code:
// Add line items to a stock movement.
request('POST', `stockMovements/${$.data.stockMovementId}`, {
  body: {
    lineItems: $.data.items.map((item, index) => ({
      'product.id': item.productId,
      quantityRequested: item.quantity,
      sortOrder: (index + 1) * 100,
    })),
  },
});

Update Stock Movement Status.code:
// Transition a stock movement's status.
// Statuses: CREATED, PENDING, REQUESTED, VALIDATED, CHECKING, PICKING, PICKED, ISSUED, CANCELED.
request('POST', `stockMovements/${$.data.stockMovementId}/status`, {
  body: {
    status: 'REQUESTED',
  },
});

Create Location.code:
// Create a location (e.g. a new district health facility).
request('POST', 'locations', {
  body: {
    name: $.data.facilityName, // e.g. 'Kisumu District Hospital'
    description: $.data.description,
    locationNumber: $.data.facilityCode,
    locationType: { id: $.data.locationTypeId },
  },
});

List Products.code:
// List products matching a search term.
get('products', {
  query: {
    q: 'paracetamol', // free-text search on name, codes, brand, etc.
    max: 50, // page size
    offset: 0,
  },
});

Get Product Stock Availability.code:
// Get available lots (with quantities and expiry) of a product at a location.
request('GET', `products/${$.data.productId}/availableItems`, {
  query: { 'location.id': $.data.facilityId },
});

List Stock Movements.code:
// List outbound stock movements from a depot that have been issued.
request('GET', 'stockMovements', {
  query: {
    direction: 'OUTBOUND', // or 'INBOUND'
    'origin.id': $.data.warehouseId,
    status: 'ISSUED',
    exclude: 'lineItems', // smaller payload
    max: 100,
  },
});

List Locations.code:
// List all depot locations.
get('locations', {
  query: { locationTypeCode: 'DEPOT', max: 100 },
});
